        function parseAIOutput(rawText) {
            const data = {};
            if (!rawText || typeof rawText !== 'string') {
                console.warn("AI output is empty or not a string:", rawText);
                return data;
            }
            const lines = rawText.trim().split(/\r?\n/);
            let currentKey = null;
            let accumulatingValue = "";

            lines.forEach(line => {
                const parts = line.split(/:(.*)/s);
                let key = parts[0].trim();
                let value = parts.length > 1 ? parts[1].trim() : "";

                if (["心情", "衣物", "动作", "小穴湿润度", "内心想法", "好感度", "快感值", "堕落值", "好感度事件", "日记", "随笔", "攻略论坛"].includes(key)) {
                    if (currentKey && accumulatingValue) { // Save previous accumulated value
                         if (data[currentKey]) { // Append if key already exists (e.g. for multiline 日记)
                            data[currentKey] += "\n" + accumulatingValue.trim();
                        } else {
                            data[currentKey] = accumulatingValue.trim();
                        }
                    }
                    currentKey = key; // Set new key
                    accumulatingValue = value; // Start new value accumulation
                } else if (currentKey) { 
                    // This line doesn't start with a known key, so append it to the current key's value
                    accumulatingValue += "\n" + line.trim();
                }
            });

            // Save the last accumulated value
            if (currentKey && accumulatingValue) {
                if (data[currentKey]) {
                     data[currentKey] += "\n" + accumulatingValue.trim();
                } else {
                    data[currentKey] = accumulatingValue.trim();
                }
            }

            // Map to internal data keys
            const mappedData = {
                mood: data["心情"],
                clothing: data["衣物"],
                action: data["动作"],
                wetness: data["小穴湿润度"],
                thoughts: data["内心想法"],
