                diary: data["日记"],
                essay: data["随笔"],
                forumContent: data["攻略论坛"]
            };
            // console.log("Parsed Data:", mappedData);
            return mappedData;
        }

        function displayData(data) {
            const querySelectorSafe = (selector, parent = document) => {
                const el = parent.querySelector(selector);
                if (!el) { /* console.warn(`Element not found for selector: ${selector}`); */ return { textContent: '', innerHTML: '', style: {} }; }
                return el;
            };

            const updateSimpleStatus = (id, valueKey, iconContent) => {
                const item = document.getElementById(id);
                if (item) {
                    const valueArea = item.querySelector('.status-item-value-area');
                    if (valueArea) valueArea.textContent = data[valueKey] || 'N/A';
                    // const iconSpan = item.querySelector('.label-icon');
                    // if (iconSpan && iconContent) iconSpan.textContent = iconContent;
                }
            };

            updateSimpleStatus('statusMood', 'mood', '💖');
            updateSimpleStatus('statusClothing', 'clothing', '👚');
            updateSimpleStatus('statusAction', 'action', '💃');
            updateSimpleStatus('statusWetness', 'wetness', '💧');
            updateSimpleStatus('statusThoughts', 'thoughts', '💬');
            updateSimpleStatus('statusEvent', 'event', '💌');

            const updateProgressStatus = (id, valueKey, min, max, barId) => {
                const rawValue = data[valueKey];
                let numericValue = 0;
                let changeText = '';

                if (rawValue) {
                    const match = String(rawValue).match(/^([\d.\-]+)\s*(?:\((.*?)\))?$/);
                    if (match) {
                        numericValue = parseFloat(match[1]);
                        if (match[2]) changeText = `(${match[2]})`;
                    } else {
                        const directNumber = parseFloat(rawValue);
                        if (!isNaN(directNumber)) {
                            numericValue = directNumber;
                        } else {
                            querySelectorSafe(`#${barId} ~ .status-item-header .status-item-value-area.value-only`).textContent = rawValue || 'N/A';
                            querySelectorSafe(`#${barId} .progress-bar-text`).textContent = 'N/A';
                            querySelectorSafe(`#${barId} .progress-bar-fill`).style.width = '0%';
                            return;
                        }
                    }
                } else {
                     querySelectorSafe(`#${barId} ~ .status-item-header .status-item-value-area.value-only`).textContent = 'N/A';
                     querySelectorSafe(`#${barId} .progress-bar-text`).textContent = 'N/A';
                     querySelectorSafe(`#${barId} .progress-bar-fill`).style.width = '0%';
                     return;
                }

                numericValue = Math.max(min, Math.min(max, numericValue));
                const totalRange = max - min;
                const percentage = totalRange === 0 ? 0 : ((numericValue - min) / totalRange) * 100;

                const barFill = querySelectorSafe(`#${barId} .progress-bar-fill`);
                const barText = querySelectorSafe(`#${barId} .progress-bar-text`);

                barFill.style.width = `${percentage}%`;
                barText.textContent = `${numericValue} / ${max} ${changeText}`;
                const valueOnlySpan = querySelectorSafe(`#${id} .status-item-header .value-only`);
                if(valueOnlySpan) valueOnlySpan.textContent = ''; 
            };

            updateProgressStatus('statusAffection', 'affection', -100, 200, 'affectionProgressBar');
            updateProgressStatus('statusPleasure', 'pleasure', 0, 150, 'pleasureProgressBar');
            updateProgressStatus('statusCorruption', 'corruption', 0, 100, 'corruptionProgressBar');

            const diaryTextElement = document.getElementById('diaryText');
