                    const suggestions = data.forumContent.split(/\n\s*\n/).map(s => s.trim()).filter(s => s);
                    if (suggestions.length <= 1 && data.forumContent.includes('\n')) {
                        // If split by double newline yields few, try single for lists
                        const singleLineSuggestions = data.forumContent.split('\n').map(s => s.trim()).filter(s => s);
                        if (singleLineSuggestions.length > 1) suggestions.splice(0, suggestions.length, ...singleLineSuggestions);
                    }


                    if (suggestions.length > 0) {
                        suggestions.forEach(suggestionText => {
                            const postDiv = document.createElement('div');
                            postDiv.className = 'forum-post suggestion-post';

                            const headerDiv = document.createElement('div');
                            headerDiv.className = 'forum-post-header';
                            headerDiv.innerHTML = `<span class="post-sender-icon">💡</span> 攻略AI小助手`;

                            const contentDiv = document.createElement('div');
                            contentDiv.className = 'forum-post-content';
                            contentDiv.textContent = suggestionText;

                            postDiv.appendChild(headerDiv);
                            postDiv.appendChild(contentDiv);
                            forumContainer.appendChild(postDiv);
                        });
                    } else { // Single block of text if no clear separators
                         const postDiv = document.createElement('div');
                         postDiv.className = 'forum-post suggestion-post';
                         const contentDiv = document.createElement('div');
                         contentDiv.className = 'forum-post-content';
                         contentDiv.textContent = data.forumContent;
                         postDiv.appendChild(contentDiv);
                         forumContainer.appendChild(postDiv);
                    }
                } else {
                    forumContainer.innerHTML = '<div class="forum-post"><div class="forum-post-content">暂无攻略建议。</div></div>';
                }
            }
        }

