                this.canvas = canvas; this.ctx = canvas.getContext('2d');
                this.x = x; this.y = y; this.size = size;
                this.speedY = speed * (Math.random() * 0.2 + 0.1); // Slower wisps
                this.speedX = (Math.random() - 0.5) * speed * 0.1;
                this.opacity = Math.random() * 0.3 + 0.1; 
                this.maxOpacity = this.opacity * (Math.random() * 0.4 + 1);
                this.opacityFadeSpeed = 0.003 + Math.random() * 0.003;
                this.life = 0; this.maxLife = 100 + Math.random() * 60; // Longer life
                const colors = [ `rgba(255, 195, 209,`, `rgba(255, 209, 199,`, `rgba(231, 180, 231,`];
                this.colorBase = colors[Math.floor(Math.random() * colors.length)];
            }
            draw() {
                this.ctx.save(); this.ctx.beginPath();
                const gradient = this.ctx.createRadialGradient(this.x, this.y, 0, this.x, this.y, this.size);
                gradient.addColorStop(0, this.colorBase + this.opacity + ')');
                gradient.addColorStop(0.7, this.colorBase + (this.opacity * 0.4) + ')');
                gradient.addColorStop(1, this.colorBase + '0)');
                this.ctx.fillStyle = gradient;
                this.ctx.arc(this.x, this.y, this.size, 0, Math.PI * 2);
                this.ctx.fill(); this.ctx.restore();
            }
            update() {
                this.y -= this.speedY; this.x += this.speedX; this.life++;
                if (this.life < this.maxLife / 2) {
                    this.opacity += this.opacityFadeSpeed;
                    if (this.opacity > this.maxOpacity) this.opacity = this.maxOpacity;
                } else { this.opacity -= this.opacityFadeSpeed; }
                if (this.y < -this.size || this.opacity <= 0 || this.life >= this.maxLife) { this.reset(); }
                this.draw();
            }
            reset() {
                this.y = this.canvas.height + this.size + Math.random() * 30;
                this.x = Math.random() * this.canvas.width;
                this.opacity = Math.random() * 0.15 + 0.05;
                this.maxOpacity = this.opacity * (Math.random() * 0.5 + 1.1);
                this.speedY = (Math.random() * 0.2 + 0.05) * (Math.random() * 0.2 + 0.1);
                this.speedX = (Math.random() - 0.5) * 0.15 * (Math.random() * 0.2 + 0.05);
                this.life = 0;
            }
