                forumContent: data["攻略论坛"]
            };
            // console.log("Parsed Data:", mappedData);
            return mappedData;
        }

        function displayData(data) {
            const querySelectorSafe = (selector, parent = document) => {
                const el = parent.querySelector(selector);
                if (!el) { /* console.warn(`Element not found for selector: ${selector}`); */ return { textContent: '', innerHTML: '', style: {} }; }
                return el;
            };

            const updateSimpleStatus = (id, valueKey, iconContent) => {
                const item = document.getElementById(id);
                if (item) {
                    const valueArea = item.querySelector('.status-item-value-area');
                    if (valueArea) valueArea.textContent = data[valueKey] || 'N/A';
                    // const iconSpan = item.querySelector('.label-icon');
                    // if (iconSpan && iconContent) iconSpan.textContent = iconContent;
                }
            };

            updateSimpleStatus('statusMood', 'mood', '💖');
            updateSimpleStatus('statusClothing', 'clothing', '👚');
            updateSimpleStatus('statusAction', 'action', '💃');
            updateSimpleStatus('statusWetness', 'wetness', '💧');
            updateSimpleStatus('statusThoughts', 'thoughts', '💬');
            updateSimpleStatus('statusEvent', 'event', '💌');

            const updateProgressStatus = (id, valueKey, min, max, barId) => {
                const rawValue = data[valueKey];
                let numericValue = 0;
                let changeText = '';

                if (rawValue) {
                    const match = String(rawValue).match(/^([\d.\-]+)\s*(?:\((.*?)\))?$/);
                    if (match) {
                        numericValue = parseFloat(match[1]);
                        if (match[2]) changeText = `(${match[2]})`;
                    } else {
                        const directNumber = parseFloat(rawValue);
                        if (!isNaN(directNumber)) {
                            numericValue = directNumber;
                        } else {
                            querySelectorSafe(`#${barId} ~ .status-item-header .status-item-value-area.value-only`).textContent = rawValue || 'N/A';
                            querySelectorSafe(`#${barId} .progress-bar-text`).textContent = 'N/A';
                            querySelectorSafe(`#${barId} .progress-bar-fill`).style.width = '0%';
                            return;
                        }
                    }
                } else {
                     querySelectorSafe(`#${barId} ~ .status-item-header .status-item-value-area.value-only`).textContent = 'N/A';
                     querySelectorSafe(`#${barId} .progress-bar-text`).textContent = 'N/A';
                     querySelectorSafe(`#${barId} .progress-bar-fill`).style.width = '0%';
                     return;
                }

                numericValue = Math.max(min, Math.min(max, numericValue));
                const totalRange = max - min;
                const percentage = totalRange === 0 ? 0 : ((numericValue - min) / totalRange) * 100;

                const barFill = querySelectorSafe(`#${barId} .progress-bar-fill`);
                const barText = querySelectorSafe(`#${barId} .progress-bar-text`);

                barFill.style.width = `${percentage}%`;
                barText.textContent = `${numericValue} / ${max} ${changeText}`;
                const valueOnlySpan = querySelectorSafe(`#${id} .status-item-header .value-only`);
                if(valueOnlySpan) valueOnlySpan.textContent = ''; 
            };

            updateProgressStatus('statusAffection', 'affection', -100, 200, 'affectionProgressBar');
            updateProgressStatus('statusPleasure', 'pleasure', 0, 150, 'pleasureProgressBar');
            updateProgressStatus('statusCorruption', 'corruption', 0, 100, 'corruptionProgressBar');

            const diaryTextElement = document.getElementById('diaryText');
            if (diaryTextElement) { diaryTextElement.textContent = data.diary || '暂无日记内容。';}

            const essayTextElement = document.getElementById('essayText');
            if (essayTextElement) { essayTextElement.textContent = data.essay || '暂无随笔内容。';}

            const forumContainer = document.getElementById('forumContainer');
            if (forumContainer) {
                forumContainer.innerHTML = ''; // Clear previous content
                if (data.forumContent) {
                    // Assuming AI gives suggestions separated by newlines, or as a list.
                    // Let's split by double newline first, then single newline as fallback.
                    const suggestions = data.forumContent.split(/\n\s*\n/).map(s => s.trim()).filter(s => s);
                    if (suggestions.length <= 1 && data.forumContent.includes('\n')) {
                        // If split by double newline yields few, try single for lists
                        const singleLineSuggestions = data.forumContent.split('\n').map(s => s.trim()).filter(s => s);
                        if (singleLineSuggestions.length > 1) suggestions.splice(0, suggestions.length, ...singleLineSuggestions);
                    }


                    if (suggestions.length > 0) {
                        suggestions.forEach(suggestionText => {
                            const postDiv = document.createElement('div');
                            postDiv.className = 'forum-post suggestion-post';

                            const headerDiv = document.createElement('div');
                            headerDiv.className = 'forum-post-header';
                            headerDiv.innerHTML = `<span class="post-sender-icon">💡</span> 攻略AI小助手`;

                            const contentDiv = document.createElement('div');
                            contentDiv.className = 'forum-post-content';
                            contentDiv.textContent = suggestionText;

                            postDiv.appendChild(headerDiv);
                            postDiv.appendChild(contentDiv);
                            forumContainer.appendChild(postDiv);
                        });
                    } else { // Single block of text if no clear separators
                         const postDiv = document.createElement('div');
                         postDiv.className = 'forum-post suggestion-post';
                         const contentDiv = document.createElement('div');
                         contentDiv.className = 'forum-post-content';
                         contentDiv.textContent = data.forumContent;
                         postDiv.appendChild(contentDiv);
                         forumContainer.appendChild(postDiv);
                    }
                } else {
                    forumContainer.innerHTML = '<div class="forum-post"><div class="forum-post-content">暂无攻略建议。</div></div>';
                }
            }
        }

        class Wisp { 
             constructor(canvas, x, y, size, speed) {
                this.canvas = canvas; this.ctx = canvas.getContext('2d');
                this.x = x; this.y = y; this.size = size;
                this.speedY = speed * (Math.random() * 0.2 + 0.1); // Slower wisps
                this.speedX = (Math.random() - 0.5) * speed * 0.1;
                this.opacity = Math.random() * 0.3 + 0.1; 
                this.maxOpacity = this.opacity * (Math.random() * 0.4 + 1);
                this.opacityFadeSpeed = 0.003 + Math.random() * 0.003;
                this.life = 0; this.maxLife = 100 + Math.random() * 60; // Longer life
                const colors = [ `rgba(255, 195, 209,`, `rgba(255, 209, 199,`, `rgba(231, 180, 231,`];
                this.colorBase = colors[Math.floor(Math.random() * colors.length)];
            }
            draw() {
                this.ctx.save(); this.ctx.beginPath();
                const gradient = this.ctx.createRadialGradient(this.x, this.y, 0, this.x, this.y, this.size);
                gradient.addColorStop(0, this.colorBase + this.opacity + ')');
                gradient.addColorStop(0.7, this.colorBase + (this.opacity * 0.4) + ')');
                gradient.addColorStop(1, this.colorBase + '0)');
                this.ctx.fillStyle = gradient;
                this.ctx.arc(this.x, this.y, this.size, 0, Math.PI * 2);
                this.ctx.fill(); this.ctx.restore();
            }
            update() {
                this.y -= this.speedY; this.x += this.speedX; this.life++;
                if (this.life < this.maxLife / 2) {
                    this.opacity += this.opacityFadeSpeed;
                    if (this.opacity > this.maxOpacity) this.opacity = this.maxOpacity;
                } else { this.opacity -= this.opacityFadeSpeed; }
                if (this.y < -this.size || this.opacity <= 0 || this.life >= this.maxLife) { this.reset(); }
                this.draw();
            }
            reset() {
                this.y = this.canvas.height + this.size + Math.random() * 30;
                this.x = Math.random() * this.canvas.width;
                this.opacity = Math.random() * 0.15 + 0.05;
                this.maxOpacity = this.opacity * (Math.random() * 0.5 + 1.1);
                this.speedY = (Math.random() * 0.2 + 0.05) * (Math.random() * 0.2 + 0.1);
                this.speedX = (Math.random() - 0.5) * 0.15 * (Math.random() * 0.2 + 0.05);
                this.life = 0;
            }
        }
        let wisps = []; let wispRAF;
        function initWisps(canvasElement) { 
            if (!canvasElement) return;
            const ctx = canvasElement.getContext('2d');
            let resizeTimeout;
            const setCanvasSize = () => {
                canvasElement.width = canvasElement.offsetWidth;
                canvasElement.height = canvasElement.offsetHeight;
            };
            setCanvasSize(); wisps = [];
            const numberOfWisps = 15; // Fewer wisps for subtlety
            for (let i = 0; i < numberOfWisps; i++) {
                const size = Math.random() * 2 + 1; 
                const x = Math.random() * canvasElement.width;
                const y = Math.random() * canvasElement.height;
                const speed = Math.random() * 0.2 + 0.05; 
                wisps.push(new Wisp(canvasElement, x, y, size, speed));
            }
            function animateWisps() {
                if (!canvasElement.isConnected) { if (wispRAF) cancelAnimationFrame(wispRAF); return; }
                ctx.clearRect(0, 0, canvasElement.width, canvasElement.height);
                wisps.forEach(w => w.update());
                wispRAF = requestAnimationFrame(animateWisps);
            }
            if (wispRAF) cancelAnimationFrame(wispRAF); animateWisps();
            if (canvasElement._resizeListener) { window.removeEventListener('resize', canvasElement._resizeListener); }
            canvasElement._resizeListener = () => {
                clearTimeout(resizeTimeout);
                resizeTimeout = setTimeout(() => {
                    setCanvasSize();
                    wisps.forEach(w => {
                         if (w.x > canvasElement.width + w.size || w.x < -w.size) w.reset();
                         if (w.y > canvasElement.height + w.size || w.y < -w.size) w.reset();
                    });
                }, 100);
            };
            window.addEventListener('resize', canvasElement._resizeListener);
        }

        document.addEventListener('DOMContentLoaded', () => {
            const statusTitleBar = document.getElementById('statusTitleBar');
